function icon(name, opts){
  opts = opts || {};
  var size = opts.size || 16, cls = opts.cls ? (' class="'+opts.cls+'"') : '';
  var set = ICON_SETS[ICON_SET] || ICON_SETS.lucide;
  if(set.kind === 'emoji'){
    var e = set.paths[name];
    if(e) return '<span'+(opts.cls ? ' class="emoji-icon '+opts.cls+'"' : ' class="emoji-icon"')+' style="font-size:'+Math.round(size*.95)+'px;width:'+size+'px;height:'+size+'px" aria-hidden="true">'+e+'</span>';
    set = ICON_SETS.lucide;
  }
  var d = set.paths[name];
  if(!d){ set = ICON_SETS.lucide; d = set.paths[name] || ''; }
  var attrs = set.kind === 'stroke' ? 'fill="'+(opts.fill||'none')+'" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"' : set.kind === 'fill' ? 'fill="currentColor"' : 'fill="none"';
  return '<svg'+cls+' width="'+size+'" height="'+size+'" viewBox="0 0 24 24" '+attrs+' aria-hidden="true">'+d+'</svg>';
}
